<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\CatalogOptionsService;

Auth::requirePermission('catalog.manage');$tenantId=em_require_tenant();$productId=(int)($_GET['id']??$_POST['product_id']??0);$p=$pdo->prepare('SELECT * FROM products WHERE id=? AND tenant_id=?');$p->execute([$productId,$tenantId]);$product=$p->fetch();if(!$product){http_response_code(404);exit('Produto não encontrado.');}$service=new CatalogOptionsService();
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');try{
    if($action==='group-save'){$service->saveGroup($tenantId,$productId,['name'=>$_POST['name']??'','min_select'=>$_POST['min_select']??0,'max_select'=>$_POST['max_select']??1,'sort_order'=>$_POST['sort_order']??0,'active'=>isset($_POST['active'])],($id=(int)($_POST['id']??0))?:null);em_flash('ok','Grupo salvo.');}
    elseif($action==='option-save'){$price=(int)round((float)str_replace(',','.',(string)($_POST['price_delta']??'0'))*100);$service->saveOption($tenantId,(int)($_POST['group_id']??0),['name'=>$_POST['name']??'','price_delta_cents'=>$price,'sort_order'=>$_POST['sort_order']??0,'active'=>isset($_POST['active'])],($id=(int)($_POST['id']??0))?:null);em_flash('ok','Opção salva.');}
    elseif($action==='group-delete'){$pdo->prepare('DELETE FROM product_option_groups WHERE id=? AND tenant_id=? AND product_id=?')->execute([(int)$_POST['id'],$tenantId,$productId]);em_flash('ok','Grupo removido.');}
    elseif($action==='option-delete'){$pdo->prepare('DELETE po FROM product_options po JOIN product_option_groups g ON g.id=po.group_id WHERE po.id=? AND po.tenant_id=? AND g.product_id=?')->execute([(int)$_POST['id'],$tenantId,$productId]);em_flash('ok','Opção removida.');}
    elseif($action==='combo-save'){$components=[];foreach(($_POST['component_qty']??[])as$id=>$qty){$q=(float)str_replace(',','.',(string)$qty);if($q>0)$components[(int)$id]=$q;}$service->setComboComponents($tenantId,$productId,$components);em_flash('ok','Composição do combo salva.');}
}catch(Throwable $e){em_flash('error',$e->getMessage());}em_go('product-options',['id'=>$productId]);}
$g=$pdo->prepare('SELECT * FROM product_option_groups WHERE tenant_id=? AND product_id=? ORDER BY sort_order,id');$g->execute([$tenantId,$productId]);$groups=$g->fetchAll();$options=[];if($groups){$ids=array_column($groups,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$o=$pdo->prepare('SELECT * FROM product_options WHERE group_id IN ('.$marks.') ORDER BY sort_order,id');$o->execute($ids);foreach($o->fetchAll()as$r)$options[(int)$r['group_id']][]=$r;}$all=$pdo->prepare('SELECT id,name,product_type FROM products WHERE tenant_id=? AND id<>? AND active=1 ORDER BY name');$all->execute([$tenantId,$productId]);$products=$all->fetchAll();$c=$pdo->prepare('SELECT component_product_id,quantity FROM product_combo_items WHERE tenant_id=? AND combo_product_id=?');$c->execute([$tenantId,$productId]);$components=[];foreach($c->fetchAll()as$r)$components[(int)$r['component_product_id']]=$r['quantity'];
em_header('Opções e combo · '.$product['name'],'products');?>
<div class="actions" style="margin-bottom:16px"><a class="button secondary" href="<?= Security::e(em_url('/?route=products&edit='.$productId)) ?>">← Voltar ao produto</a></div><div class="grid" style="grid-template-columns:minmax(300px,1fr) minmax(0,2fr)"><section class="card"><h2>Novo grupo de opções</h2><p class="muted">Ex.: Tamanho, Escolha o molho, Adicionais.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="group-save"><input type="hidden" name="product_id" value="<?= $productId ?>"><label class="span-2">Nome<input name="name" required></label><label>Mínimo<input type="number" min="0" name="min_select" value="0"></label><label>Máximo<input type="number" min="1" name="max_select" value="1"></label><label>Ordem<input type="number" name="sort_order" value="0"></label><label class="checkbox"><input type="checkbox" name="active" checked> Ativo</label><button class="primary span-2">Criar grupo</button></form></section><section><?php foreach($groups as$gr):?><article class="card" style="margin-bottom:16px"><div class="section-head"><div><h2><?= Security::e($gr['name']) ?></h2><span class="muted">mín. <?= (int)$gr['min_select'] ?> · máx. <?= (int)$gr['max_select'] ?></span></div><form method="post" onsubmit="return confirm('Remover este grupo e suas opções?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="group-delete"><input type="hidden" name="product_id" value="<?= $productId ?>"><input type="hidden" name="id" value="<?= (int)$gr['id'] ?>"><button class="secondary">Excluir</button></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Opção</th><th>Acréscimo</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($options[(int)$gr['id']]??[] as$op):?><tr><td><?= Security::e($op['name']) ?></td><td><?= em_money((int)$op['price_delta_cents']) ?></td><td><?= $op['active']?'Ativa':'Inativa' ?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="option-delete"><input type="hidden" name="product_id" value="<?= $productId ?>"><input type="hidden" name="id" value="<?= (int)$op['id'] ?>"><button class="secondary">Excluir</button></form></td></tr><?php endforeach;?></tbody></table></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="option-save"><input type="hidden" name="product_id" value="<?= $productId ?>"><input type="hidden" name="group_id" value="<?= (int)$gr['id'] ?>"><label class="span-2">Nova opção<input name="name" required placeholder="Ex.: Bacon extra"></label><label>Acréscimo R$<input name="price_delta" inputmode="decimal" value="0,00"></label><label>Ordem<input type="number" name="sort_order" value="0"></label><label class="checkbox span-2"><input type="checkbox" name="active" checked> Ativa</label><button class="secondary span-2">Adicionar opção</button></form></article><?php endforeach;?></section></div><section class="card" style="margin-top:16px"><div class="section-head"><div><h2>Composição de combo</h2><p class="muted">Defina produtos consumidos quando este item for vendido. Ciclos são bloqueados automaticamente.</p></div><span class="badge"><?= $components?'Combo':'Produto simples' ?></span></div><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="combo-save"><input type="hidden" name="product_id" value="<?= $productId ?>"><div class="table-wrap"><table class="table"><thead><tr><th>Componente</th><th>Quantidade consumida</th></tr></thead><tbody><?php foreach($products as$cp):?><tr><td><?= Security::e($cp['name']) ?></td><td><input style="max-width:140px" name="component_qty[<?= (int)$cp['id'] ?>]" inputmode="decimal" value="<?= Security::e((string)($components[(int)$cp['id']]??'')) ?>" placeholder="0"></td></tr><?php endforeach;?></tbody></table></div><button class="primary" style="margin-top:14px">Salvar composição</button></form></section><?php em_footer();
